<script setup lang="ts">
import {ref,onUnmounted,watch} from 'vue';import {useApplication} from '../../application';import {useActionOwnerSelection} from './useActionOwnerSelection';import type {Person} from '../../shared/api/meeting-options';import {ApiError} from '../../shared/api/client';
const props=defineProps<{meetingId:string;elementId:string;revisionToken:string;enabled:boolean;hasIdentity:boolean}>(),emit=defineEmits<{save:[person:Person|null];denied:[cause:unknown]}>(),app=useApplication(),query=ref('');
const state=useActionOwnerSelection(app.options.people,()=>app.session.current.value?.actor.enterpriseId??null,()=>[props.meetingId,props.elementId,props.revisionToken],()=>props.enabled&&app.minutesScopeReady.value);
watch(()=>[app.session.current.value?.actor.enterpriseId,props.meetingId,props.elementId,props.revisionToken],()=>query.value='');watch(state.error,cause=>{if(cause instanceof ApiError&&[401,403].includes(cause.status))emit('denied',cause);});
onUnmounted(state.dispose);
</script>
<template><section class="action-owner-selection" aria-label="企业负责人选择"><h4>选择企业负责人</h4><p>从当前目录中选择并保存；负责人身份不会授予会议访问权。也可清除企业身份后手写显示名。</p><label>搜索企业负责人<input v-model="query" :disabled="!enabled||state.busy.value"/></label><button class="btn" :disabled="!enabled||state.busy.value" @click="state.search(query)">查找负责人</button><p v-if="state.busy.value" role="status">正在读取人员…</p><p v-if="state.error.value" role="alert">人员目录暂不可用，请重试。</p><ul><li v-for="person in state.people.value" :key="person.stableId"><button class="btn" :disabled="!enabled||!person.active||state.busy.value" @click="state.choose(person)">选为负责人：{{person.displayName}} · {{person.department??person.stableId}}{{person.active?'':'（不可选择）'}}</button></li></ul><button v-if="state.nextCursor.value" class="btn" :disabled="!enabled||state.busy.value" @click="state.search(query,true)">下一页负责人</button><p v-if="state.selected.value">待保存：{{state.selected.value.displayName}}</p><button class="btn" :disabled="!enabled||!state.selected.value||state.busy.value" @click="emit('save',state.selected.value)">保存所选负责人</button><button v-if="hasIdentity" class="btn" :disabled="!enabled||state.busy.value" @click="emit('save',null)">清除企业负责人身份</button></section></template>
<style scoped>.action-owner-selection{border-top:1px solid var(--border);margin-top:16px;padding-top:10px}.action-owner-selection p{font-size:13px;color:var(--muted)}.action-owner-selection label{display:block}.action-owner-selection input{display:block;width:min(420px,100%);padding:8px;box-sizing:border-box;margin:8px 0}.action-owner-selection ul{padding-left:0;list-style:none}</style>
